#r "nuget: MSBuild.StructuredLogger, 2.2.405"
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

Console.WriteLine("=== Projects ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} (SourceFilePath: {p.SourceFilePath})");
}

Console.WriteLine("\n=== Warnings ===");
var warnings = build.FindChildrenRecursive<Warning>();
foreach (var w in warnings)
{
    var proj = w.GetNearestParent<Project>()?.Name ?? "unknown";
    Console.WriteLine($"  [{proj}] {w.Code}: {w.Text}");
}

// Look for package references
Console.WriteLine("\n=== Items containing Newtonsoft ===");
var items = build.FindChildrenRecursive<Item>();
foreach (var item in items)
{
    if (item.ToString().Contains("Newtonsoft"))
        Console.WriteLine($"  {item}");
}

Console.WriteLine("\n=== NamedNodes containing PackageReference ===");
var namedNodes = build.FindChildrenRecursive<NamedNode>();
foreach (var n in namedNodes)
{
    if (n.Name != null && n.Name.Contains("PackageReference"))
        Console.WriteLine($"  {n.Name} -> {n}");
    if (n.ToString().Contains("Newtonsoft"))
        Console.WriteLine($"  [Newtonsoft] {n}");
}
EOF
